class Data {}; // Complex/expensive object

// 1. Guaranteed Copy Elision (C++17)
// Returns a prvalue (temporary object)
Data make_temp() {
    return Data{}; // Elision is mandated: Constructed directly in destination.
}

// 2. Named Return Value Optimization (NRVO)
// Returns a local named object
Data make_named() {
    Data result;
    // ... logic
    return result; // Elision is optional optimization (highly likely).
}

// Usage: Both calls result in zero copy/move operations typically.
// Data d1 = make_temp();
// Data d2 = make_named();
